import { type Template, type InsertTemplate, type ProcessingJob, type InsertProcessingJob, type User, type InsertUser, type TemplateFieldMappings, type DocumentType, type InsertDocumentType, type DocumentVersion, type InsertDocumentVersion, getFieldNamesFromMappings } from "@shared/schema";
import { randomUUID } from "crypto";

export interface IStorage {
  // User methods
  getUser(id: string): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  // Document type methods
  createDocumentType(documentType: InsertDocumentType): Promise<DocumentType>;
  getDocumentType(id: string): Promise<DocumentType | undefined>;
  getDocumentTypes(): Promise<DocumentType[]>;
  getDocumentTypeByCode(code: string): Promise<DocumentType | undefined>;
  deleteDocumentType(id: string): Promise<boolean>;

  // Document version methods
  createDocumentVersion(documentVersion: InsertDocumentVersion): Promise<DocumentVersion>;
  getDocumentVersion(id: string): Promise<DocumentVersion | undefined>;
  getDocumentVersionsByType(documentTypeId: string): Promise<DocumentVersion[]>;
  detectDocumentVersion(ocrText: string, documentTypeId: string): Promise<DocumentVersion | undefined>;

  // Template methods
  createTemplate(template: InsertTemplate): Promise<Template>;
  getTemplate(id: string): Promise<Template | undefined>;
  getTemplates(): Promise<Template[]>;
  getTemplatesByVersion(documentVersionId: string): Promise<Template[]>;
  getTemplatesByDocumentType(documentTypeId: string): Promise<Template[]>;
  updateTemplate(id: string, updates: Partial<Template>): Promise<Template | undefined>;
  deleteTemplate(id: string): Promise<boolean>;

  // Processing job methods
  createProcessingJob(job: InsertProcessingJob): Promise<ProcessingJob>;
  getProcessingJob(id: string): Promise<ProcessingJob | undefined>;
  getProcessingJobs(): Promise<ProcessingJob[]>;
  updateProcessingJob(id: string, updates: Partial<ProcessingJob>): Promise<ProcessingJob | undefined>;
  deleteProcessingJob(id: string): Promise<boolean>;

  // Initialization method
  initializeDefaultData(): Promise<void>;
}

export class MemStorage implements IStorage {
  private users: Map<string, User> = new Map();
  private templates: Map<string, Template> = new Map();
  private processingJobs: Map<string, ProcessingJob> = new Map();
  private documentTypes: Map<string, DocumentType> = new Map();
  private documentVersions: Map<string, DocumentVersion> = new Map();

  constructor() {
    // Add default marriage certificate template with new fieldMappings structure
    const defaultFieldMappings: TemplateFieldMappings = {
      "serial_indicator": {
        instances: [{
          coordinates: {
            page: 1,
            rect: { x: 100, y: 750, width: 150, height: 20 },
            units: 'pdf_points',
            origin: 'bottom-left'
          },
          detectionConfidence: 0.95,
          detectionMethod: 'template_predefined'
        }],
        fieldDefinition: {
          type: 'text',
          label: 'Serial Indicator',
          description: 'Certificate serial number or identifier',
          validation: { required: true, maxLength: 50 }
        }
      },
      "registry_country": {
        instances: [{
          coordinates: {
            page: 1,
            rect: { x: 100, y: 700, width: 200, height: 20 },
            units: 'pdf_points',
            origin: 'bottom-left'
          },
          detectionConfidence: 0.95,
          detectionMethod: 'template_predefined'
        }],
        fieldDefinition: {
          type: 'text',
          label: 'Registry Country',
          description: 'Country where the marriage was registered',
          validation: { required: true, maxLength: 100 }
        }
      },
      "registry_department": {
        instances: [{
          coordinates: {
            page: 1,
            rect: { x: 100, y: 650, width: 200, height: 20 },
            units: 'pdf_points',
            origin: 'bottom-left'
          },
          detectionConfidence: 0.95,
          detectionMethod: 'template_predefined'
        }],
        fieldDefinition: {
          type: 'text',
          label: 'Registry Department',
          description: 'Department or state where registered',
          validation: { required: true, maxLength: 100 }
        }
      },
      "registry_municipality": {
        instances: [{
          coordinates: {
