        font: font,
        color: rgb(0, 0, 0),
      });

      page.drawText('Net Worth', {
        x: 470,
        y: currentY,
        size: 10,
        font: font,
        color: rgb(0, 0, 0),
      });

      page.drawText('31.', {
        x: 520,
        y: currentY,
        size: 10,
        font: font,
        color: rgb(0, 0, 0),
      });

      currentY -= 40;

      // Date section
      page.drawText('Date:', {
        x: 50,
        y: currentY,
        size: 10,
        font: font,
        color: rgb(0, 0, 0),
      });

      page.drawText(extractedFieldValues.date || 'N/A', {
        x: 90,
        y: currentY,
        size: 10,
        font: boldFont,
        color: rgb(0, 0, 0),
      });

      currentY -= 40;

      // Footer note
      page.drawText('This is a computer-generated DIAN tax form document', {
        x: 50,
        y: 50,
        size: 8,
        font: font,
        color: rgb(0.5, 0.5, 0.5),
      });

      page.drawText(`Generated on: ${new Date().toLocaleDateString()}`, {
        x: 50,
        y: 35,
        size: 8,
        font: font,
        color: rgb(0.5, 0.5, 0.5),
      });

      console.log('Successfully created DIAN tax form PDF from scratch');

      // Save the PDF
      const filledPdfBytes = await pdfDoc.save();
      return Buffer.from(filledPdfBytes);

    } catch (error) {
      console.error('DIAN tax form creation failed:', error);
      throw error;
    }
  }

  private drawLabelValuePair(page: any, font: any, x: number, y: number, label: string, value: string) {
    // Draw label
    page.drawText(label, {
      x: x,
      y: y,
      size: 10,
      font: font,
      color: rgb(0, 0, 0),
    });

    // Draw value below label
    page.drawText(value, {
      x: x,
      y: y - 15,
      size: 10,
      font: font,
      color: rgb(0, 0, 0),
    });
  }
}

