                            <p className="text-blue-600 dark:text-blue-400">
                              Our system will automatically detect XXX markers and map field positions during upload.
                            </p>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="flex space-x-3 mt-6">
                <Button 
