      const userPrompt = `Analyze these marker contexts and suggest field information:

Marker patterns: ${markers.map(m => m.pattern).join(', ')}
Contexts: ${uniqueContexts.join('\n')}

Document excerpt: ${fullText.substring(0, 1000)}...`;

