import * as url from 'url';
import { promisify } from 'util';

/**
 * SSRF Protection utility for validating and safely handling external URLs
 */
export class SSRFProtection {
  // Allowed hostnames for external requests
  private static readonly ALLOWED_HOSTS = [
    'storage.googleapis.com',
    'storage.cloud.google.com',
    '*.storage.googleapis.com', // For bucket-specific subdomains
  ];

  // Blocked internal network ranges
  private static readonly BLOCKED_IP_RANGES = [
    /^127\./,                    // Loopback
    /^10\./,                     // Private Class A
    /^172\.(1[6-9]|2[0-9]|3[0-1])\./,  // Private Class B
    /^192\.168\./,               // Private Class C
    /^169\.254\./,               // Link-local
    /^::1$/,                     // IPv6 loopback
    /^fe80:/,                    // IPv6 link-local
    /^fc00:/,                    // IPv6 unique local
    /^fd00:/,                    // IPv6 unique local
  ];

  // Allowed content types for downloaded files
  private static readonly ALLOWED_CONTENT_TYPES = [
    'application/pdf',
    'image/jpeg',
    'image/jpg', 
    'image/png',
    'image/tiff',
    'image/tif',
    'image/gif',
    'image/bmp',
    'image/webp',
    'application/octet-stream', // Some GCS files may use this
  ];

  // Security limits
  private static readonly MAX_DOWNLOAD_SIZE = 10 * 1024 * 1024; // 10MB
  private static readonly REQUEST_TIMEOUT = 10000; // 10 seconds
  private static readonly MAX_REDIRECTS = 3;

  /**
   * Validates if a URL is safe for external requests
   * @param targetUrl - The URL to validate
   * @returns true if URL is safe
   * @throws Error if URL is dangerous or not allowed
   */
  static async validateUrl(targetUrl: string): Promise<boolean> {
    if (!targetUrl || typeof targetUrl !== 'string') {
      throw new Error('Invalid URL: URL must be a non-empty string');
    }

    let parsedUrl: URL;
    try {
      parsedUrl = new URL(targetUrl);
    } catch (error) {
      throw new Error(`Invalid URL format: ${targetUrl}`);
    }

    // Only allow HTTPS for external requests (except localhost for dev)
    if (parsedUrl.protocol !== 'https:' && parsedUrl.protocol !== 'http:') {
      throw new Error(`Unsupported protocol: ${parsedUrl.protocol}. Only HTTPS and HTTP are allowed.`);
    }

    // Special handling for localhost (dev environment)
    if (this.isLocalhostUrl(parsedUrl)) {
      return true; // Localhost is handled by PathValidator
    }

    // Validate hostname against allowlist
    if (!this.isHostAllowed(parsedUrl.hostname)) {
      throw new Error(`Host not allowed: ${parsedUrl.hostname}. Only Google Cloud Storage URLs are permitted.`);
    }

    // Check for blocked IP addresses
    if (this.isIpBlocked(parsedUrl.hostname)) {
      throw new Error(`Access to internal IP address blocked: ${parsedUrl.hostname}`);
    }

    // Resolve hostname to IP and check again
    try {
      const resolvedIps = await this.resolveHostname(parsedUrl.hostname);
      for (const ip of resolvedIps) {
        if (this.isIpBlocked(ip)) {
          throw new Error(`Resolved IP address is blocked: ${ip} for hostname ${parsedUrl.hostname}`);
        }
      }
    } catch (error) {
      // If we can't resolve, be conservative and block
      throw new Error(`Unable to resolve hostname for security validation: ${parsedUrl.hostname}`);
    }

    return true;
  }

  /**
   * Creates a secure HTTP request configuration
   * @param targetUrl - The target URL 
   * @returns Secure request configuration
   */
  static createSecureRequestConfig(targetUrl: string): any {
    return {
      timeout: this.REQUEST_TIMEOUT,
      maxRedirects: this.MAX_REDIRECTS,
      maxContentLength: this.MAX_DOWNLOAD_SIZE,
      validateStatus: (status: number) => status < 400,
      headers: {
        'User-Agent': 'Replit-DocumentProcessor/1.0',
        'Accept': this.ALLOWED_CONTENT_TYPES.join(', '),
      },
    };
  }

  /**
   * Validates response content type
   * @param contentType - The response content type
   * @returns true if content type is allowed
   * @throws Error if content type is not allowed
   */
  static validateContentType(contentType: string): boolean {
    if (!contentType) {
      throw new Error('No content type specified in response');
    }

    const normalizedType = contentType.toLowerCase().split(';')[0].trim();

    if (!this.ALLOWED_CONTENT_TYPES.includes(normalizedType)) {
      throw new Error(`Content type not allowed: ${normalizedType}. Allowed types: ${this.ALLOWED_CONTENT_TYPES.join(', ')}`);
    }

    return true;
  }

  /**
   * Validates response size
   * @param contentLength - The response content length
   * @returns true if size is within limits
   * @throws Error if size exceeds limits
   */
  static validateResponseSize(contentLength: number): boolean {
    if (contentLength > this.MAX_DOWNLOAD_SIZE) {
      throw new Error(`Response size ${contentLength} bytes exceeds maximum allowed size of ${this.MAX_DOWNLOAD_SIZE} bytes`);
    }
    return true;
  }

  /**
   * Checks if URL is localhost
   */
  private static isLocalhostUrl(parsedUrl: URL): boolean {
    return parsedUrl.hostname === 'localhost' || 
           parsedUrl.hostname === '127.0.0.1' ||
           parsedUrl.hostname === '::1';
  }

  /**
   * Checks if hostname is in allowlist
   */
  private static isHostAllowed(hostname: string): boolean {
    const normalizedHostname = hostname.toLowerCase();

    return this.ALLOWED_HOSTS.some(allowedHost => {
      if (allowedHost.startsWith('*.')) {
        const domain = allowedHost.substring(2);
        return normalizedHostname.endsWith('.' + domain) || normalizedHostname === domain;
      }
      return normalizedHostname === allowedHost;
    });
  }

  /**
   * Checks if IP address is blocked
   */
  private static isIpBlocked(ip: string): boolean {
    return this.BLOCKED_IP_RANGES.some(range => range.test(ip));
  }

  /**
   * Resolves hostname to IP addresses
   */
  private static async resolveHostname(hostname: string): Promise<string[]> {
    const dns = require('dns');
    const lookup = promisify(dns.lookup);

    try {
      // Try IPv4 first
      const result = await lookup(hostname, { family: 4, all: true });
      return Array.isArray(result) ? result.map(r => r.address) : [result.address];
    } catch (ipv4Error) {
      try {
        // Fallback to IPv6
        const result = await lookup(hostname, { family: 6, all: true });
        return Array.isArray(result) ? result.map(r => r.address) : [result.address];
      } catch (ipv6Error) {
        throw new Error(`Cannot resolve hostname: ${hostname}`);
      }
    }
  }

  /**
   * Creates a timeout promise for request abortion
   */
  static createTimeoutPromise(timeout: number): Promise<never> {
    return new Promise((_, reject) => {
      setTimeout(() => {
        reject(new Error(`Request timeout after ${timeout}ms`));
      }, timeout);
    });
  }
}

server/security/pathValidator.test.ts.content:
import { PathValidator } from './pathValidator';
import * as path from 'path';
import * as fs from 'fs';

// Mock fs for testing
jest.mock('fs');
const mockedFs = fs as jest.Mocked<typeof fs>;

describe('PathValidator', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('validateAndSanitizePath', () => {
    it('should accept valid paths within allowed directories', () => {
      const result = PathValidator.validateAndSanitizePath('test/file.pdf', 'uploads');
      expect(result).toContain('uploads');
      expect(result).toContain('test');
      expect(result).toContain('file.pdf');
    });

    it('should reject paths with directory traversal attempts', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('../../../etc/passwd', 'uploads');
      }).toThrow('contains dangerous pattern');
    });

    it('should reject paths with .. components', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('test/../../../etc/passwd', 'uploads');
      }).toThrow('contains dangerous pattern');
    });

    it('should reject paths with null bytes', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('test\x00file.pdf', 'uploads');
      }).toThrow('contains dangerous pattern');
    });

    it('should reject paths with Windows reserved names', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('CON', 'uploads');
      }).toThrow('contains dangerous pattern');

      expect(() => {
        PathValidator.validateAndSanitizePath('aux.txt', 'uploads');
      }).toThrow('contains dangerous pattern');
    });

    it('should reject empty or non-string paths', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('', 'uploads');
      }).toThrow('path must be a non-empty string');

      expect(() => {
        PathValidator.validateAndSanitizePath(null as any, 'uploads');
      }).toThrow('path must be a non-empty string');
    });

    it('should reject paths that are too long', () => {
      const longPath = 'a'.repeat(300);
      expect(() => {
        PathValidator.validateAndSanitizePath(longPath, 'uploads');
      }).toThrow('path length exceeds');
    });

    it('should reject invalid root directories', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('test.pdf', 'invalid_root');
      }).toThrow('not allowed');
    });

    it('should reject paths with just dots as components', () => {
      expect(() => {
        PathValidator.validateAndSanitizePath('test/...', 'uploads');
      }).toThrow('Invalid path component');

      expect(() => {
        PathValidator.validateAndSanitizePath('..', 'uploads');
      }).toThrow('contains dangerous pattern');
    });

    it('should normalize slashes and remove leading slashes', () => {
      const result = PathValidator.validateAndSanitizePath('//test\\file.pdf', 'uploads');
      expect(result).toContain(path.join('uploads', 'test', 'file.pdf'));
    });

    it('should prevent path traversal to parent directories', () => {
      // This should fail because the resolved path would go outside the allowed root
      expect(() => {
        // Create a path that when joined and resolved would escape the allowed directory
        const maliciousPath = '../outside.txt';
        PathValidator.validateAndSanitizePath(maliciousPath, 'uploads');
      }).toThrow('contains dangerous pattern');
    });
  });

  describe('mapLocalhostUrlToPath', () => {
    it('should map public-objects URLs correctly', () => {
      const url = new URL('http://localhost:5000/public-objects/templates/test.pdf');
      const result = PathValidator.mapLocalhostUrlToPath(url);
      expect(result).toContain('public-objects');
      expect(result).toContain('templates');
      expect(result).toContain('test.pdf');
    });

    it('should map objects URLs to uploads directory', () => {
      const url = new URL('http://localhost:5000/objects/documents/file.pdf');
      const result = PathValidator.mapLocalhostUrlToPath(url);
      expect(result).toContain('uploads');
      expect(result).toContain('documents');
      expect(result).toContain('file.pdf');
    });

    it('should map attached_assets URLs correctly', () => {
      const url = new URL('http://localhost:5000/attached_assets/image.png');
      const result = PathValidator.mapLocalhostUrlToPath(url);
      expect(result).toContain('attached_assets');
      expect(result).toContain('image.png');
    });

    it('should reject URLs with path traversal attempts', () => {
      expect(() => {
        const url = new URL('http://localhost:5000/public-objects/../../../etc/passwd');
        PathValidator.mapLocalhostUrlToPath(url);
      }).toThrow('contains dangerous pattern');
    });

    it('should reject unsupported URL paths', () => {
      expect(() => {
        const url = new URL('http://localhost:5000/unsupported/path');
        PathValidator.mapLocalhostUrlToPath(url);
      }).toThrow('Unsupported localhost URL path');
    });

    it('should handle URL encoded paths securely', () => {
      expect(() => {
        // URL encoded "../" 
        const url = new URL('http://localhost:5000/public-objects/%2e%2e%2f%2e%2e%2f%2e%2e%2fetc%2fpasswd');
        PathValidator.mapLocalhostUrlToPath(url);
      }).toThrow('contains dangerous pattern');
    });
  });

  describe('validateFileExists', () => {
    it('should return true for existing files', () => {
      mockedFs.statSync.mockReturnValue({
        isFile: () => true,
        size: 1024
      } as any);

      const result = PathValidator.validateFileExists('/path/to/file.pdf');
      expect(result).toBe(true);
      expect(mockedFs.statSync).toHaveBeenCalledWith('/path/to/file.pdf');
    });

    it('should throw error for non-existent files', () => {
      mockedFs.statSync.mockImplementation(() => {
        const error = new Error('ENOENT') as any;
        error.code = 'ENOENT';
        throw error;
      });

      expect(() => {
        PathValidator.validateFileExists('/path/to/nonexistent.pdf');
      }).toThrow('File not found');
    });

    it('should throw error for directories', () => {
      mockedFs.statSync.mockReturnValue({
        isFile: () => false,
        size: 4096
      } as any);

      expect(() => {
        PathValidator.validateFileExists('/path/to/directory');
      }).toThrow('Path is not a file');
    });

    it('should handle other filesystem errors', () => {
      mockedFs.statSync.mockImplementation(() => {
        throw new Error('Permission denied');
      });

      expect(() => {
        PathValidator.validateFileExists('/path/to/file.pdf');
      }).toThrow('File access error');
    });
  });

  describe('validateFileSize', () => {
    it('should return file size for files within limits', () => {
      mockedFs.statSync.mockReturnValue({
        size: 1024
      } as any);

      const result = PathValidator.validateFileSize('/path/to/file.pdf', 2048);
      expect(result).toBe(1024);
    });

    it('should use default size limit if not provided', () => {
      mockedFs.statSync.mockReturnValue({
        size: 1024
      } as any);

      const result = PathValidator.validateFileSize('/path/to/file.pdf');
      expect(result).toBe(1024);
    });

    it('should throw error for files exceeding size limit', () => {
      mockedFs.statSync.mockReturnValue({
        size: 1024 * 1024 * 15 // 15MB
      } as any);

      expect(() => {
        PathValidator.validateFileSize('/path/to/largefile.pdf', 10 * 1024 * 1024); // 10MB limit
      }).toThrow('File too large');
    });
  });

  describe('Edge cases and security tests', () => {
    it('should handle various path injection attempts', () => {
      const maliciousPaths = [
        '../',
        '..\\',
        '....///',
        '%2e%2e%2f',
        '..%2f',
        '..%5c',
        '%2e%2e/',
        '.%2e/',
        'test/../test',
        'test\\..\\test',
      ];

      maliciousPaths.forEach(maliciousPath => {
        expect(() => {
          PathValidator.validateAndSanitizePath(maliciousPath, 'uploads');
        }).toThrow();
      });
    });

    it('should reject paths with invalid characters', () => {
      const invalidPaths = [
        'test<file.pdf',
        'test>file.pdf', 
        'test|file.pdf',
        'test?file.pdf',
        'test*file.pdf',
        'test"file.pdf',
        'test:file.pdf',
      ];

      invalidPaths.forEach(invalidPath => {
        expect(() => {
          PathValidator.validateAndSanitizePath(invalidPath, 'uploads');
        }).toThrow('contains dangerous pattern');
      });
    });
  });
});

