import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useParams, useLocation, Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Skeleton } from "@/components/ui/skeleton";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { 
  FileText, 
  Clock, 
  Eye, 
  CheckCircle, 
  XCircle, 
  AlertCircle, 
  AlertTriangle,
  Info,
  Calendar,
  User,
  Settings,
  ArrowLeft,
  Zap,
  Target,
  Download,
  Play,
  Edit,
  Save,
  RefreshCw,
  FileCheck,
  Upload,
  Trash2
} from "lucide-react";
import { format } from "date-fns";

interface Template {
  id: string;
  name: string;
  description: string;
  filePath: string;
  fieldMappings: Record<string, any>;
  isAutoCreated?: boolean;
  sourceDocumentPath?: string;
  templateType?: string;
  detectionMetadata?: any;
  validationRules?: any;
  createdAt: string;
  updatedAt?: string;
}

interface ProcessingJob {
  id: string;
  originalFilePath: string;
  userEmail: string;
  status: string;
  extractedData?: Record<string, string>;
  templateId?: string;
  extractedFieldValues?: Record<string, string>;
  generatedDocumentPath?: string;
  errorMessage?: string;
  createdAt: string;
  updatedAt: string;
}

const statusColors = {
  'pending_review': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
  'uploading': 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200',
  'ocr': 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200',
  'extraction': 'bg-indigo-100 text-indigo-800 dark:bg-indigo-900 dark:text-indigo-200',
  'mapping': 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900 dark:text-cyan-200',
  'generation': 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200',
  'completed': 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
  'error': 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200',
  'validation_failed': 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'
};

const statusIcons = {
  'pending_review': Clock,
  'uploading': FileText,
  'ocr': Eye,
  'extraction': Zap,
  'mapping': Target,
  'generation': Settings,
  'completed': CheckCircle,
  'error': XCircle,
  'validation_failed': AlertTriangle
};

export default function AdminJobReview() {
  const { id } = useParams<{ id: string }>();
  const [, navigate] = useLocation();
  const [editableFields, setEditableFields] = useState<Record<string, string>>({});
  const [isEditingFields, setIsEditingFields] = useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>("");

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get document type ID from URL parameters as a fallback since database column is temporarily disabled
  const urlParams = new URLSearchParams(window.location.search);
  const documentTypeFromUrl = urlParams.get('documentTypeId');

  // Fetch specific job details
  const { data: job, isLoading: jobLoading, error: jobError } = useQuery<ProcessingJob>({
    queryKey: ['/api/processing-jobs', id],
    enabled: !!id,
  });

  // Fetch templates for template selection
  const { data: templates = [] } = useQuery<Template[]>({
    queryKey: ['/api/templates'],
  });

  // Initialize editable fields when job data is loaded
  useEffect(() => {
    if (!job) return;

    // Get template field mappings
    const template = templates.find(t => t.id === job.templateId);
    const templateFieldMappings = template?.fieldMappings || {};

    // Start with extracted data
    const ocrFields = job.extractedData || {};
    const processedFields = job.extractedFieldValues || {};

    // Create intelligent field mapping from OCR to template
    const mappedTemplateFields = createFieldMapping(ocrFields, templateFieldMappings);

    // Merge all field sources
    const mergedFields = {
      ...ocrFields,           // Original OCR fields
      ...processedFields,     // Processed fields
      ...mappedTemplateFields // Mapped template fields
    };

    // Successfully mapped OCR fields to template fields

    if (Object.keys(mergedFields).length > 0) {
      setEditableFields(mergedFields);
    }
    if (job.templateId) {
      setSelectedTemplateId(job.templateId);
    }
  }, [job, templates]);

  // Function to detect document type for category-based template selection
  const getDocumentTypeForProcessing = () => {
    // Try to get from URL parameters first (if passed from admin interface)
    if (documentTypeFromUrl) return documentTypeFromUrl;

    // TEMPORARY: Known document types from the logs - you would replace this with actual logic
    // For now, detect the document type based on OCR content if available
    if (job?.extractedData) {
      const ocrText = Object.values(job.extractedData).join(' ').toLowerCase();

      // Simple detection based on OCR content
      if (ocrText.includes('registro civil') || ocrText.includes('nacimiento')) {
        return '7e216115-54a2-4e19-b1a7-9106ac06eaa6'; // Birth Certificate
      }
      if (ocrText.includes('dian') || ocrText.includes('rut')) {
        return '2d130b0e-77e5-4df4-90a7-b35c0d19cbef'; // DIAN Tax Form  
      }
      if (ocrText.includes('marriage') || ocrText.includes('matrimonio')) {
        return 'fb8c12f5-4bf8-4c23-bc4e-fe5fe6d8ff41'; // Marriage Certificate
      }
    }

    return undefined; // Fallback to automatic detection in backend
  };

  // Manual OCR processing mutation
  const processOCRMutation = useMutation({
    mutationFn: async () => {
      // Detect and include document type ID in the request body to enable category-based template selection
      const documentTypeId = getDocumentTypeForProcessing();
      const requestBody = documentTypeId ? { selectedDocumentTypeId: documentTypeId } : {};
      console.log('🎯 Processing with document type ID:', documentTypeId);
      const res = await apiRequest('POST', `/api/processing-jobs/${id}/process`, requestBody);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/processing-jobs', id] });
      toast({
        title: "OCR Processing Started",
        description: "OCR extraction and field processing has been initiated.",
      });
    },
    onError: (error) => {
      // Check if this is a validation failure
      if (error.message && error.message.includes('Template validation failed')) {
        toast({
          title: "Template Validation Failed",
          description: "The selected template is not compatible with your document. Please choose a different template that better matches your document structure.",
          variant: "destructive",
        });
      } else {
        toast({
          title: "Processing Error",
          description: error.message || "An error occurred while processing the document.",
          variant: "destructive",
        });
      }
    },
  });

  // Update job mutation (for status changes, template selection, field values)
  const updateJobMutation = useMutation({
    mutationFn: async (updates: Partial<ProcessingJob>) => {
      const res = await apiRequest('PATCH', `/api/processing-jobs/${id}`, updates);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/processing-jobs', id] });
      toast({
        title: "Job Updated",
        description: "Processing job has been updated successfully.",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Generate document mutation
  const generateDocumentMutation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest('POST', `/api/processing-jobs/${id}/generate`, {
        extractedFieldValues: editableFields,
        templateId: selectedTemplateId
      });

      // Handle PDF response - create download link
      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `generated_document_${id}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);

      return { success: true };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/processing-jobs', id] });
      toast({
        title: "Document Generated",
        description: "The document has been generated and downloaded successfully.",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Delete processing job mutation
  const deleteJobMutation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest('DELETE', `/api/processing-jobs/${id}`);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/processing-jobs'] });
      toast({
        title: "Request Deleted",
        description: "The processing request has been deleted successfully.",
      });
      // Navigate back to requests list
      navigate("/admin/requests");
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // State for delete confirmation dialog
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);

  // Handle template selection change
  const handleTemplateChange = (templateId: string) => {
    setSelectedTemplateId(templateId);
    updateJobMutation.mutate({ templateId });
  };

  // Handle field value changes
  const handleFieldChange = (fieldName: string, value: string) => {
    setEditableFields(prev => ({
      ...prev,
      [fieldName]: value
    }));
  };

  // Save field changes
  const handleSaveFields = () => {
    updateJobMutation.mutate({ extractedFieldValues: editableFields });
    setIsEditingFields(false);
  };

  // Get template name
  const getTemplateName = (templateId?: string) => {
    if (!templateId) return 'No Template';
    const template = templates.find(t => t.id === templateId);
    return template ? template.name : 'Unknown Template';
  };

  // Get file name from path
  const getFileName = (filePath?: string) => {
    if (!filePath) return 'No file name';
    return filePath.split('/').pop() || filePath;
  };

  // Get field mappings from selected template
  const getTemplateFieldMappings = () => {
    if (!selectedTemplateId) return {};
    const template = templates.find(t => t.id === selectedTemplateId);
    return template?.fieldMappings || {};
  };

  // Create intelligent field mapping between OCR fields and template fields
  const createFieldMapping = (ocrFields: Record<string, string>, templateFields: Record<string, any>) => {
    const mappingRules: Record<string, string> = {
      // OCR field name -> Template field name
      'first_name': 'party_a_names',
      'other_names': 'party_a_names', // Could be combined or separate
      'first_surname': 'party_a_surnames',
      'second_surname': 'party_a_surnames',
      'tax_identification_number': 'party_a_document_number',
      'nit': 'party_a_document_number',
    };

    const mappedFields: Record<string, string> = {};

    // Apply mapping rules
    Object.entries(ocrFields).forEach(([ocrFieldName, value]) => {
      const templateFieldName = mappingRules[ocrFieldName];
      if (templateFieldName && templateFields[templateFieldName]) {
        // If template field already has a value, combine them with proper spacing
        if (mappedFields[templateFieldName]) {
          mappedFields[templateFieldName] = `${mappedFields[templateFieldName]} ${value}`.trim();
        } else {
          mappedFields[templateFieldName] = value;
        }
      }
    });

    return mappedFields;
  };

  // Render template matching alerts
  const renderTemplateMatchingAlerts = () => {
    const versionDetectionResults = (job as any)?.versionDetectionResults;
    if (!versionDetectionResults) return null;

    // Check for template mismatch alerts first
    if (versionDetectionResults.templateMismatchAlert) {
      const alert = versionDetectionResults.templateMismatchAlert;
      const isWarning = alert.severity === 'warning';

      return (
        <Alert variant={isWarning ? "destructive" : "default"} className="mb-4" data-testid="alert-template-mismatch">
          {isWarning ? <AlertTriangle className="h-4 w-4" /> : <Info className="h-4 w-4" />}
          <AlertTitle>{alert.title}</AlertTitle>
          <AlertDescription>
            <p className="mb-2">{alert.message}</p>
            <div className="text-sm space-y-1">
              {alert.detectedDocumentType && (
                <p><strong>Detected:</strong> {alert.detectedDocumentType}</p>
              )}
              {alert.selectedTemplateName && (
                <p><strong>Selected Template:</strong> {alert.selectedTemplateName}</p>
              )}
              {alert.detectedFieldCount !== undefined && alert.templateFieldCount !== undefined && (
                <p><strong>Field Analysis:</strong> {alert.matchingFieldCount || 0} matching out of {alert.templateFieldCount} template fields ({alert.detectedFieldCount} detected in document)</p>
              )}
              <p><strong>Recommendation:</strong> {alert.recommendation}</p>
            </div>
          </AlertDescription>
        </Alert>
      );
    }

    // Check if this is the new intelligent template matching results
    if (versionDetectionResults.templateMatchResults) {
      const { templateMatchResults, selectedTemplate } = versionDetectionResults;

      if (!selectedTemplate || selectedTemplate.confidence === 'none') {
        return (
          <Alert variant="destructive" className="mb-4">
            <AlertTriangle className="h-4 w-4" />
            <AlertTitle>No Good Template Match Found</AlertTitle>
            <AlertDescription>
              The system could not find a suitable template that matches the OCR extracted fields. 
              {templateMatchResults && templateMatchResults.length > 0 ? (
                <div className="mt-2">
                  <p>Template matching results:</p>
                  <ul className="list-disc list-inside mt-1">
                    {templateMatchResults.slice(0, 3).map((result: any, index: number) => (
                      <li key={index} className="text-sm">
                        {result.templateName}: {(result.score * 100).toFixed(1)}% match ({result.confidence} confidence)
                      </li>
                    ))}
                  </ul>
                  <p className="mt-2 text-sm font-medium">Please manually select an appropriate template or create a new one.</p>
                </div>
              ) : (
                <p className="mt-2 text-sm">Please manually select a template from the dropdown above.</p>
              )}
            </AlertDescription>
          </Alert>
        );
      } else if (selectedTemplate.confidence === 'low') {
        return (
          <Alert variant="default" className="mb-4 border-yellow-200 bg-yellow-50 dark:border-yellow-800 dark:bg-yellow-900/20">
            <Info className="h-4 w-4" />
            <AlertTitle>Low Confidence Template Match</AlertTitle>
            <AlertDescription>
              The system selected "{selectedTemplate.templateName}" with {(selectedTemplate.score * 100).toFixed(1)}% confidence. 
              Please review the field mappings below and verify they are correct.
            </AlertDescription>
          </Alert>
        );
      } else if (selectedTemplate.confidence === 'high') {
        return (
          <Alert variant="default" className="mb-4 border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20">
            <CheckCircle className="h-4 w-4 text-green-600" />
            <AlertTitle>High Confidence Template Match</AlertTitle>
            <AlertDescription>
              Successfully matched template "{selectedTemplate.templateName}" with {(selectedTemplate.score * 100).toFixed(1)}% confidence.
              {templateMatchResults && templateMatchResults.length > 1 && (
                <span className="ml-2 text-sm">({templateMatchResults.length} templates evaluated)</span>
              )}
            </AlertDescription>
          </Alert>
        );
      }
    }

    return null;
  };

  // Get comprehensive field list from template + extracted values
  const getComprehensiveFieldList = () => {
    const templateFieldMappings = getTemplateFieldMappings();
    const templateFieldNames = Object.keys(templateFieldMappings);

    // Get all field names from both sources
    const ocrExtractedFieldNames = Object.keys(job?.extractedData || {});
    const processedFieldNames = Object.keys(job?.extractedFieldValues || {});
    const editableFieldNames = Object.keys(editableFields || {});

    // Combine all field names and remove duplicates
    const allFieldNames = Array.from(new Set([
      ...templateFieldNames, 
      ...ocrExtractedFieldNames, 
      ...processedFieldNames, 
      ...editableFieldNames
    ]));

    // Create comprehensive field data
    return allFieldNames.map(fieldName => {
      const fieldMapping = templateFieldMappings[fieldName];
      const extractedValue = editableFields?.[fieldName] || '';
      const fieldDefinition = fieldMapping?.fieldDefinition;

      // Determine field source
      const isFromTemplate = !!fieldMapping;
      const isFromOCR = ocrExtractedFieldNames.includes(fieldName);
      const isFromProcessed = processedFieldNames.includes(fieldName);

      const field = {
        name: fieldName,
        value: extractedValue,
        label: fieldDefinition?.label || fieldName.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
        type: fieldDefinition?.type || 'text',
        description: fieldDefinition?.description,
        isFromTemplate,
        isExtracted: isFromOCR || isFromProcessed,
        isFromOCR,
        isFromProcessed
      };

      return field;
    }).sort((a, b) => {
      // Sort by: template fields first, then OCR extracted fields, then others
      if (a.isFromTemplate && !b.isFromTemplate) return -1;
      if (!a.isFromTemplate && b.isFromTemplate) return 1;
      if (a.isFromOCR && !b.isFromOCR) return -1;
      if (!a.isFromOCR && b.isFromOCR) return 1;
      return a.label.localeCompare(b.label);
    });
  };

  // Render status badge
  const StatusBadge = ({ status }: { status: string }) => {
    const Icon = statusIcons[status as keyof typeof statusIcons] || AlertCircle;
    const colorClass = statusColors[status as keyof typeof statusColors] || 'bg-gray-100 text-gray-800';

    return (
      <Badge className={`${colorClass} flex items-center gap-1`} data-testid={`status-${status}`}>
        <Icon className="h-3 w-3" />
        {status.replace('_', ' ').toUpperCase()}
      </Badge>
    );
  };

  // Loading state
  if (jobLoading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
        <header className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
          <div className="max-w-6xl mx-auto px-6">
            <div className="flex justify-between items-center h-16">
              <div className="flex items-center space-x-4">
                <Skeleton className="h-6 w-6" />
                <Skeleton className="h-6 w-48" />
              </div>
              <Skeleton className="h-8 w-32" />
            </div>
          </div>
        </header>

        <div className="max-w-6xl mx-auto px-6 py-8">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <Card>
              <CardHeader>
                <Skeleton className="h-6 w-32" />
              </CardHeader>
              <CardContent className="space-y-4">
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-4 w-1/2" />
              </CardContent>
            </Card>
            <Card>
              <CardHeader>
                <Skeleton className="h-6 w-32" />
              </CardHeader>
              <CardContent className="space-y-4">
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-4 w-1/2" />
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    );
  }

  // Error state
  if (jobError || !job) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
        <header className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
          <div className="max-w-6xl mx-auto px-6">
            <div className="flex justify-between items-center h-16">
              <div className="flex items-center space-x-4">
                <User className="h-6 w-6 text-gray-700 dark:text-gray-300" />
                <h1 className="text-lg font-semibold text-gray-900 dark:text-white">
                  Job Review
                </h1>
              </div>
              <Link href="/admin/requests">
                <Button variant="outline" size="sm" data-testid="button-back-requests">
                  <ArrowLeft className="h-4 w-4 mr-2" />
                  Back to Requests
                </Button>
              </Link>
            </div>
          </div>
        </header>

        <div className="max-w-6xl mx-auto px-6 py-8">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              {jobError ? "Failed to load job details." : "Job not found."} Please try going back and selecting a different job.
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <header className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="max-w-6xl mx-auto px-6">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <User className="h-6 w-6 text-gray-700 dark:text-gray-300" data-testid="logo-job-review" />
              <h1 className="text-lg font-semibold text-gray-900 dark:text-white" data-testid="page-title">
                Job Review: {getFileName(job.originalFilePath)}
              </h1>
              <StatusBadge status={job.status} />
            </div>
            <div className="flex items-center space-x-4">
              {/* Delete button for pending/failed requests */}
              {(job.status === 'pending_review' || job.status === 'uploading' || job.status === 'error' || job.status === 'validation_failed') && (
                <Dialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
                  <DialogTrigger asChild>
                    <Button 
                      variant="destructive" 
                      size="sm" 
                      data-testid="button-delete-request"
                    >
                      <Trash2 className="h-4 w-4 mr-2" />
                      Delete Request
                    </Button>
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Delete Processing Request</DialogTitle>
                      <DialogDescription>
                        Are you sure you want to delete this processing request? This action cannot be undone.
                        The uploaded file and all extracted data will be permanently removed.
                      </DialogDescription>
                    </DialogHeader>
                    <div className="flex items-center space-x-2 pt-4">
                      <Button
                        variant="outline"
                        onClick={() => setShowDeleteDialog(false)}
                        data-testid="button-cancel-delete"
                      >
                        Cancel
                      </Button>
                      <Button
                        variant="destructive"
                        onClick={() => {
                          deleteJobMutation.mutate();
                          setShowDeleteDialog(false);
                        }}
                        disabled={deleteJobMutation.isPending}
                        data-testid="button-confirm-delete"
                      >
                        {deleteJobMutation.isPending ? (
                          <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                        ) : (
                          <Trash2 className="h-4 w-4 mr-2" />
                        )}
                        Delete Request
                      </Button>
                    </div>
                  </DialogContent>
                </Dialog>
              )}

              <Link href="/admin/requests">
                <Button variant="outline" size="sm" data-testid="button-back-requests">
                  <ArrowLeft className="h-4 w-4 mr-2" />
                  Back to Requests
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="max-w-6xl mx-auto px-6 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

          {/* Document Details */}
          <Card className="bg-white dark:bg-gray-800" data-testid="card-document-details">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <FileText className="h-5 w-5" />
                Document Details
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">File Name</Label>
                <p className="text-sm text-gray-900 dark:text-gray-100" data-testid="text-filename">
                  {getFileName(job.originalFilePath)}
                </p>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">File Path</Label>
                <p className="text-sm text-gray-500 dark:text-gray-400 truncate" data-testid="text-filepath">
                  {job.originalFilePath}
                </p>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">User Email</Label>
                <div className="flex items-center space-x-2">
                  <User className="h-4 w-4 text-gray-500" />
                  <p className="text-sm text-gray-900 dark:text-gray-100" data-testid="text-user-email">
                    {job.userEmail}
                  </p>
                </div>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">Created</Label>
                <p className="text-sm text-gray-900 dark:text-gray-100" data-testid="text-created">
                  {job.createdAt ? format(new Date(job.createdAt), 'PPp') : 'No date'}
                </p>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">Last Updated</Label>
                <p className="text-sm text-gray-900 dark:text-gray-100" data-testid="text-updated">
                  {job.updatedAt ? format(new Date(job.updatedAt), 'PPp') : 'No date'}
                </p>
              </div>

              {job.errorMessage && (
                <div>
                  <Label className="text-sm font-medium text-red-700 dark:text-red-300">Error Message</Label>
                  <Alert variant="destructive">
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription data-testid="text-error">
                      {job.errorMessage}
                    </AlertDescription>
                  </Alert>
                </div>
              )}

              {/* Document Preview Link */}
              <Separator />
              <div className="flex justify-center">
                <Button 
                  variant="outline" 
                  size="sm" 
                  asChild 
                  data-testid="button-view-document"
                >
                  <a href={job.originalFilePath} target="_blank" rel="noopener noreferrer">
                    <Eye className="h-4 w-4 mr-2" />
                    View Original Document
                  </a>
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Processing Controls */}
          <Card className="bg-white dark:bg-gray-800" data-testid="card-processing-controls">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Settings className="h-5 w-5" />
                Processing Controls
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">

              {/* Template Selection */}
              <div>
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">Template Selection</Label>
                <Select value={selectedTemplateId} onValueChange={handleTemplateChange}>
                  <SelectTrigger data-testid="select-template">
                    <SelectValue placeholder="Select a template" />
                  </SelectTrigger>
                  <SelectContent>
                    {templates.map((template) => (
                      <SelectItem key={template.id} value={template.id} data-testid={`option-template-${template.id}`}>
                        {template.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {selectedTemplateId && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    Selected: {getTemplateName(selectedTemplateId)}
                  </p>
                )}
              </div>

              <Separator />

              {/* Validation Failed Section */}
              {job.status === 'validation_failed' && (
                <>
                  <div className="space-y-3">
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4 text-red-600" />
                      <h3 className="font-medium text-red-900 dark:text-red-100">Validation Failed</h3>
                    </div>
                    <p className="text-sm text-red-700 dark:text-red-300">
                      The selected template is not compatible with the uploaded document format. 
                      Please select a different template that better matches your document structure.
                    </p>
                    <Alert variant="destructive" className="border-red-200">
                      <AlertTriangle className="h-4 w-4" />
                      <AlertTitle>Template Compatibility Issue</AlertTitle>
                      <AlertDescription className="text-sm">
                        {renderTemplateMatchingAlerts() ? 
                          // Extract message from the alert if available
                          (job as any)?.versionDetectionResults?.templateMismatchAlert?.message ||
                          "The selected template has very low compatibility with the document structure."
                          :
                          "Template validation failed - please select a compatible template."
                        }
                      </AlertDescription>
                    </Alert>
                  </div>
                  <Separator />
                </>
              )}

              {/* Manual Processing Controls */}
              <div className="space-y-3">
                {/* Show validation message in place of processing controls when validation fails */}
                {job.status === 'validation_failed' ? (
                  <div className="space-y-4">
                    <Alert variant="destructive" className="border-red-200">
                      <AlertTriangle className="h-4 w-4" />
                      <AlertTitle>Template Validation Failed</AlertTitle>
                      <AlertDescription className="text-sm">
                        The selected template is not compatible with your document (0.0% compatibility). 
                        Please select a different template above that better matches your document structure.
                      </AlertDescription>
                    </Alert>
                    <Button
                      onClick={() => processOCRMutation.mutate()}
                      disabled={processOCRMutation.isPending || !selectedTemplateId}
                      className="w-full"
                      variant="outline"
                      data-testid="button-retry-validation"
                    >
                      {processOCRMutation.isPending ? (
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                      ) : (
                        <Zap className="h-4 w-4 mr-2" />
                      )}
                      Retry with Selected Template
                    </Button>
                  </div>
                ) : (
                  <>
                    <Button
                      onClick={() => processOCRMutation.mutate()}
                      disabled={processOCRMutation.isPending}
                      className="w-full"
                      data-testid="button-process-ocr"
                    >
                      {processOCRMutation.isPending ? (
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                      ) : (
                        <Zap className="h-4 w-4 mr-2" />
                      )}
                      {job.status === 'pending_review' ? 'Start OCR & Field Extraction' : 'Re-process OCR & Fields'}
                    </Button>

                    {job.extractedFieldValues && selectedTemplateId && (
                      <Button
                        onClick={() => generateDocumentMutation.mutate()}
                        disabled={generateDocumentMutation.isPending}
                        className="w-full"
                        variant="default"
                        data-testid="button-generate-document"
                      >
                        {generateDocumentMutation.isPending ? (
                          <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                        ) : (
                          <FileCheck className="h-4 w-4 mr-2" />
                        )}
                        Generate Document
                      </Button>
                    )}
                  </>
                )}
              </div>

              {/* Download Generated Document */}
              {job.generatedDocumentPath && (
                <>
                  <Separator />
                  <Button
                    variant="outline"
                    className="w-full"
                    asChild
                    data-testid="button-download-generated"
                  >
                    <a href={job.generatedDocumentPath} target="_blank" rel="noopener noreferrer">
                      <Download className="h-4 w-4 mr-2" />
                      Download Generated Document
                    </a>
                  </Button>
                </>
              )}
            </CardContent>
          </Card>
        </div>

        {/* OCR Extracted Text */}
        {job.extractedData && Object.keys(job.extractedData).length > 0 && (
          <Card className="mt-6 bg-white dark:bg-gray-800" data-testid="card-extracted-text">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Eye className="h-5 w-5" />
                OCR Extracted Text
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ScrollArea className="h-60 w-full rounded-md border p-4">
                <pre className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap" data-testid="text-ocr-content">
                  {Object.entries(job.extractedData).map(([key, value]) => (
                    `${key}: ${value}\n`
                  )).join('')}
                </pre>
              </ScrollArea>
            </CardContent>
          </Card>
        )}

        {/* Template Matching Alerts */}
        {renderTemplateMatchingAlerts()}

        {/* Template Fields & Extracted Values */}
        <Card className="mt-6 bg-white dark:bg-gray-800" data-testid="card-field-values">
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Target className="h-5 w-5" />
                Template Fields & Extracted Values
              </div>
              <div className="flex items-center gap-2">
                {isEditingFields ? (
                  <>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setIsEditingFields(false)}
                      data-testid="button-cancel-edit"
                    >
                      Cancel
                    </Button>
                    <Button
                      size="sm"
                      onClick={handleSaveFields}
                      disabled={updateJobMutation.isPending}
                      data-testid="button-save-fields"
                    >
                      {updateJobMutation.isPending ? (
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                      ) : (
                        <Save className="h-4 w-4 mr-2" />
                      )}
                      Save Changes
                    </Button>
                  </>
                ) : (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setIsEditingFields(true)}
                    data-testid="button-edit-fields"
                  >
                    <Edit className="h-4 w-4 mr-2" />
                    Edit Fields
                  </Button>
                )}
              </div>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {selectedTemplateId ? (
              <div className="space-y-4">
                {getComprehensiveFieldList().length > 0 ? (
                  getComprehensiveFieldList().map((field) => (
                    <div key={field.name} className="space-y-2">
                      <div className="flex items-center gap-2">
                        <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                          {field.label}
                        </Label>
                        <div className="flex gap-1">
                          {field.isFromTemplate && (
                            <Badge variant="outline" className="text-xs px-1 py-0 h-5">
                              Template
                            </Badge>
                          )}
                          {field.isFromOCR && (
                            <Badge variant="default" className="text-xs px-1 py-0 h-5 bg-blue-100 text-blue-800">
                              OCR
                            </Badge>
                          )}
                          {field.isFromProcessed && (
                            <Badge variant="default" className="text-xs px-1 py-0 h-5 bg-green-100 text-green-800">
                              Processed
                            </Badge>
                          )}
                          {field.isFromTemplate && (!field.value || field.value.trim() === '') && (
                            <Badge variant="destructive" className="text-xs px-1 py-0 h-5">
                              Missing
                            </Badge>
                          )}
                        </div>
                      </div>
                      {field.description && (
                        <p className="text-xs text-gray-500 dark:text-gray-400">{field.description}</p>
                      )}
                      {isEditingFields ? (
                        field.type === 'multiline_text' ? (
                          <Textarea
                            value={field.value || ''}
                            onChange={(e) => handleFieldChange(field.name, e.target.value)}
                            placeholder={`Enter ${field.label}`}
                            data-testid={`input-field-${field.name}`}
                            rows={3}
                          />
                        ) : (
                          <Input
                            value={field.value || ''}
                            onChange={(e) => handleFieldChange(field.name, e.target.value)}
                            placeholder={`Enter ${field.label}`}
                            data-testid={`input-field-${field.name}`}
                            type={field.type === 'date' ? 'date' : field.type === 'number' ? 'number' : 'text'}
                          />
                        )
                      ) : (
                        <p className="text-sm text-gray-900 dark:text-gray-100 p-2 bg-gray-50 dark:bg-gray-700 rounded" data-testid={`text-field-${field.name}`}>
                          {field.value || <span className="text-gray-500 italic">No value {field.isFromTemplate ? 'extracted' : 'provided'}</span>}
                        </p>
                      )}
                    </div>
                  ))
                ) : (
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    No fields defined in the selected template.
                  </p>
                )}
              </div>
            ) : (
              <p className="text-sm text-gray-500 dark:text-gray-400">
                Please select a template first to see available fields.
              </p>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

