    if (error) {
      console.error('Error deleting template:', error);
      return false;
    }
    return true;
  }

  // Processing job methods
  async createProcessingJob(insertJob: InsertProcessingJob): Promise<ProcessingJob> {
    const { data, error } = await supabase
