        detectionPatterns: {
          keywords: [
            'REGISTRO DEL ESTADO CIVIL',
            'REGISTRO CIVIL',
            'NACIMIENTO',
            'PARTIDA DE NACIMIENTO',
            'CERTIFICADO DE NACIMIENTO',
            'QR',
            'DIGITAL',
            'FIRMADO DIGITALMENTE'
          ],
          excludeKeywords: [],
          layoutIndicators: [
            'QR_CODE',
